fun clusterSeconds(bytes: Long, blockSize: Long, bytesPerSecond: Long, machines: Int, startupSeconds: Double = 0.0): Double {
    val blocks = (bytes + blockSize - 1) / blockSize        // 37,253 blocks for 5 TB
    val busiest = (blocks + machines - 1) / machines        // 932 blocks on the busiest machine
    val busiestBytes = minOf(bytes, busiest * blockSize)    // never more than the file
    return startupSeconds + busiestBytes.toDouble() / bytesPerSecond
}

